```python
"""Graph utilities for shortest-path and reachability analysis."""
import heapq
from collections import deque
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Target: O((V+E) log V) using efficient priority queue.
    """
    if source not in graph.adj or target not in graph.adj:
        return None, []

    pq = [(0.0, source)]
    dist = {source: 0.0}
    prev = {source: None}

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist.get(u, float('inf')):
            continue

        if u == target:
            break

        for v, weight in graph.neighbors(u):
            new_dist = d + weight
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    if target not in dist:
        return None, []

    path = []
    current = target
    while current is not None:
        path.append(current)
        current = prev.get(current)
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Target: Single Dijkstra pass — O((V+E) log V).
    """
    if source not in graph.adj:
        return {}

    pq = [(0.0, source)]
    dist = {source: 0.0}
    prev = {source: None}

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist.get(u, float('inf')):
            continue

        for v, weight in graph.neighbors(u):
            new_dist = d + weight
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    result = {}
    for node in dist:
        path = []
        current = node
        while current is not None:
            path.append(current)
            current = prev.get(current)
        path.reverse()
        result[node] = (dist[node], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Target: Early-termination Dijkstra — O((k+E) log V).
    """
    if source not in graph.adj or k <= 0:
        return []

    pq = [(0.0, source)]
    dist = {source: 0.0}
    found = []

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist.get(u, float('inf')):
            continue

        if u != source:
            found.append((u, d))
            if len(found) == k:
                break

        for v, weight in graph.neighbors(u):
            new_dist = d + weight
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return found


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Target: Simple BFS — O(V + E).
    """
    if source not in graph.adj or target not in graph.adj:
        return False
    if source == target:
        return True

    visited = {source}
    q = deque([source])

    while q:
        u = q.popleft()
        if u == target:
            return True
        for v, _ in graph.neighbors(u):
            if v not in visited:
                visited.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Target: BFS/DFS on undirected adjacency — O(V + E).
    """
    # Build an undirected version of the graph
    undirected_adj = {node: [] for node in graph.nodes}
    for edge in graph._edges:
        undirected_adj[edge.src].append(edge.dst)
        undirected_adj[edge.dst].append(edge.src)

    visited = set()
    components = []

    for node in graph.nodes:
        if node not in visited:
            component = set()
            q = [node]
            visited.add(node)

            while q:
                u = q.pop()
                component.add(u)
                for v in undirected_adj[u]:
                    if v not in visited:
                        visited.add(v)
                        q.append(v)

            components.append(component)

    return components
